'use client';

import React, { useEffect, useMemo, useState } from 'react';
import { motion } from 'framer-motion';
import { Mail, Send, FileText, Settings, Loader2, Check } from 'lucide-react';
import { DashboardCard } from '../components/DashboardCard.jsx';

// --- Constants & Mock Data ---

// NOTE: The HTML must be highly resilient for email clients (inline CSS, table layout).
const WAITLIST_WELCOME_HTML = `
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Welcome to the Nest Waitlist</title>
    <style>
        /* Base styles reset */
        body, table, td, a { -webkit-text-size-adjust: 100%; -ms-text-size-adjust: 100%; }
        table, td { mso-table-lspace: 0pt; mso-table-rspace: 0pt; }
        img { -ms-interpolation-mode: bicubic; }
        a { text-decoration: none; color: #34d399; }
        /* Font stacks */
        body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; }
    </style>
</head>
<body style="margin: 0; padding: 0; background-color: #0d111d;">
    <center>
        <table border="0" cellpadding="0" cellspacing="0" width="100%" style="border-collapse: collapse; background-color: #0d111d;">
            <tr>
                <td align="center" style="padding: 0 10px;">
                    <table border="0" cellpadding="0" cellspacing="0" width="100%" style="max-width: 600px; margin: 0 auto; background-color: #0f172a; border-radius: 12px; border: 1px solid rgba(255, 255, 255, 0.08);">

                        <tr>
                            <td align="left" style="padding: 30px 40px 20px;">
                                <span style="font-family: 'Outfit', sans-serif; font-size: 28px; font-weight: 800; color: #ffffff;">Nest</span>
                                <span style="font-size: 10px; color: #10b981; margin-left: 5px;">| WEALTH OS</span>
                            </td>
                        </tr>

                        <tr>
                            <td align="left" style="padding: 20px 40px;">
                                <h1 style="margin: 0; font-size: 30px; font-weight: bold; color: #ffffff; font-family: 'Outfit', sans-serif;">
                                    Welcome, [User Name]!
                                </h1>
                                <p style="margin: 20px 0 0; font-size: 16px; line-height: 24px; color: #94a3b8;">
                                    Your spot on the waitlist has been secured. We are currently calibrating the final security protocols and will notify you when your account is ready for initiation.
                                </p>

                                <table border="0" cellpadding="0" cellspacing="0" width="100%" style="margin-top: 30px;">
                                    <tr>
                                        <td align="left" style="padding: 15px; background-color: #1e293b; border-radius: 10px; border-left: 4px solid #10b981;">
                                            <p style="margin: 0; font-size: 14px; font-weight: bold; color: #ffffff;">
                                                STATUS: <span style="color: #34d399;">MANIFEST CLEARED</span>
                                            </p>
                                            <p style="margin: 5px 0 0; font-size: 12px; color: #475569;">
                                                You are locked in for the next onboarding wave.
                                            </p>
                                        </td>
                                    </tr>
                                </table>
                            </td>
                        </tr>

                        <tr>
                            <td align="left" style="padding: 40px 40px 30px;">
                                <table border="0" cellpadding="0" cellspacing="0" width="100%" style="background-color: #1e293b; border-radius: 12px; border: 1px solid #6366f1;">
                                    <tr>
                                        <td align="center" style="padding: 25px 30px;">
                                            <p style="margin: 0 0 10px; font-size: 18px; font-weight: bold; color: #ffffff; font-family: 'Outfit', sans-serif;">
                                                BUILD YOUR NEST TOGETHER
                                            </p>
                                            <p style="margin: 0 0 20px; font-size: 14px; color: #94a3b8; max-width: 300px;">
                                                Nest is collaborative. Share this unique link with your partner to ensure you launch together.
                                            </p>

                                            <a href="[UNIQUE_REFERRAL_LINK]" target="_blank" style="display: inline-block; padding: 12px 25px; font-size: 14px; font-weight: bold; color: #0f172a; background-color: #ffffff; border-radius: 8px; text-decoration: none; box-shadow: 0 10px 20px rgba(0, 0, 0, 0.2);">
                                                Copy My Exclusive Invite Link →
                                            </a>
                                        </td>
                                    </tr>
                                </table>
                            </td>
                        </tr>

                        <tr>
                            <td align="center" style="padding: 20px 40px 30px;">
                                <p style="margin: 0; font-size: 10px; line-height: 18px; color: #475569;">
                                    This is a system generated message. Please do not reply directly to this email. 
                                    Need help? Visit our support page.
                                </p>
                            </td>
                        </tr>

                    </table>
                </td>
            </tr>
        </table>
    </center>
</body>
</html>
`;

const TEMPLATES = [
  {
    id: 'waitlist-welcome',
    name: 'Waitlist: Welcome',
    desc: 'Sent immediately after sign-up via the landing page form.',
    html: WAITLIST_WELCOME_HTML,
  },
  {
    id: 'onboarding-launch',
    name: 'Onboarding: Launch Invite',
    desc: 'Sent when the user is moved from the waitlist to an active onboarding wave.',
    html: `
        <body style="margin: 0; padding: 40px; background-color: #0d111d;">
            <center>
                <div style="max-width: 500px; background-color: #1e293b; padding: 30px; border-radius: 16px; border: 1px solid #6366f1;">
                    <h2 style="color: #6366f1; font-family: 'Outfit', sans-serif;">Your Nest is Ready!</h2>
                    <p style="color: #94a3b8; font-size: 16px;">
                        The private link to your collaborative financial operating system is now active.
                    </p>
                    <a href="#link" target="_blank" style="display: block; margin-top: 30px; padding: 15px 20px; background-color: #6366f1; color: white; text-decoration: none; border-radius: 10px; font-weight: bold;">
                        Access Your Dashboard →
                    </a>
                </div>
            </center>
        </body>
    `,
  },
];

export default function EmailTemplateAdminView({ onInteract = () => {} }) {
  const [activeTemplate, setActiveTemplate] = useState(TEMPLATES[0].id);
  const [targetUserEmail, setTargetUserEmail] = useState('test@nest.finance');
  const activeTemplateData = useMemo(() => TEMPLATES.find((t) => t.id === activeTemplate), [activeTemplate]);
  const [isSending, setIsSending] = useState(false);
  const [lastSentTime, setLastSentTime] = useState(null);

  const handleSend = () => {
    if (!activeTemplateData || isSending) return;

    setIsSending(true);
    // Simulate API call to ESP
    setTimeout(() => {
      setIsSending(false);
      setLastSentTime(new Date());
      onInteract(`Sent ${activeTemplateData.name} to ${targetUserEmail}`);
    }, 2000);
  };

  return (
    <div className="pt-2">
      {/* Small padding top to clear header in case of external use */}
      <div className="grid grid-cols-12 gap-6">
        {/* 1. Template Selector (Left Panel) */}
        <div className="col-span-12 lg:col-span-3 space-y-4">
          <DashboardCard className="p-4 flex items-center justify-between border-0 ring-1 ring-white/5 bg-slate-900/50">
            <h3 className="text-lg font-bold text-white flex items-center gap-2">
              <Mail size={18} className="text-indigo-400" /> Templates
            </h3>
            <Settings size={16} className="text-slate-500 hover:text-white cursor-pointer" onClick={() => onInteract('Open ESP Settings')} />
          </DashboardCard>

          <div className="space-y-2">
            {TEMPLATES.map((template) => (
              <motion.button
                key={template.id}
                onClick={() => setActiveTemplate(template.id)}
                className={`w-full text-left p-4 rounded-xl border transition-all duration-300 ${
                  activeTemplate === template.id
                    ? 'bg-indigo-600 border-indigo-500 shadow-lg shadow-indigo-900/40 text-white'
                    : 'bg-slate-900/40 border-white/5 hover:bg-slate-800/60 text-slate-300'
                }`}
              >
                <h4 className="font-bold text-sm">{template.name}</h4>
                <p className="text-[10px] mt-1 opacity-75">{template.desc}</p>
              </motion.button>
            ))}
          </div>
        </div>

        {/* 2. Preview & Action Panel (Right Panel) */}
        <div className="col-span-12 lg:col-span-9 space-y-6">
          <DashboardCard className="h-full border-0 ring-1 ring-white/5 bg-[#0B0F19] p-6">
            <div className="flex items-center justify-between mb-4 pb-4 border-b border-white/5">
              <div className="flex items-center gap-3">
                <FileText size={20} className="text-emerald-400" />
                <h3 className="text-xl font-bold text-white">Preview: {activeTemplateData?.name}</h3>
              </div>
              <span className="text-xs font-mono text-slate-500">Render Status: OK</span>
            </div>

            {/* Email Preview Frame */}
            <div className="relative w-full h-[600px] border border-white/10 rounded-2xl overflow-hidden shadow-2xl">
              <iframe
                srcDoc={activeTemplateData?.html}
                title="Email Preview"
                width="100%"
                height="100%"
                frameBorder="0"
                // sandbox restricts features, important for HTML emails
                sandbox="allow-same-origin allow-scripts allow-popups allow-forms"
                className="w-full h-full"
              />
            </div>

            {/* Send Action Panel */}
            <div className="mt-8 pt-6 border-t border-white/5 bg-slate-950/40 p-4 rounded-xl flex flex-col md:flex-row items-center justify-between gap-4">
              <input
                type="email"
                value={targetUserEmail}
                onChange={(e) => setTargetUserEmail(e.target.value)}
                placeholder="Test Email Address (e.g., jane@test.com)"
                className="flex-1 w-full md:w-auto px-4 py-3 rounded-xl bg-slate-800 border border-white/10 text-white placeholder-slate-500 focus:outline-none focus:border-indigo-500 transition-colors"
              />

              <div className="flex items-center gap-4 w-full md:w-auto">
                {lastSentTime && (
                  <motion.div
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    transition={{ duration: 0.5 }}
                    className="text-[10px] text-emerald-400 flex items-center gap-2"
                  >
                    <Check size={14} /> Last Sent: {lastSentTime.toLocaleTimeString()}
                  </motion.div>
                )}

                <button
                  onClick={handleSend}
                  disabled={isSending}
                  className={`px-8 py-3 rounded-xl font-bold text-xs uppercase tracking-widest transition-all flex items-center justify-center gap-2 shadow-lg w-full md:w-auto ${
                    isSending
                      ? 'bg-slate-700 text-slate-400 cursor-wait'
                      : 'bg-indigo-600 text-white hover:bg-indigo-500 shadow-indigo-900/40'
                  }`}
                >
                  {isSending ? (
                    <>
                      <motion.div animate={{ rotate: 360 }} transition={{ duration: 1, repeat: Infinity, ease: 'linear' }}>
                        <Loader2 size={16} />
                      </motion.div>
                      Sending...
                    </>
                  ) : (
                    <>
                      <Send size={16} /> Send Test Email
                    </>
                  )}
                </button>
              </div>
            </div>
          </DashboardCard>
        </div>
      </div>
    </div>
  );
}
